{"t":"say","text":"Single agent pattern: PR review agent with sandbox testing, noise filtering, and human approval gate before posting comments."}
{"t":"assume","id":"vcs-assume","text":"GitHub or GitLab webhook triggers the workflow","alt":"Custom VCS integration via API"}
{"t":"step","id":"pr-trigger","kind":"trigger","label":"PR webhook event","runs":"fc","untrusted":true,"why":"Entry point for pull request events from VCS"}
{"t":"step","id":"input-guard","kind":"guard","label":"Screen PR payload","product":"ai-guardrails","runs":"fc","why":"Validate inbound webhook for prompt injection in diff or comments"}
{"t":"step","id":"review-agent","kind":"agent","label":"Code review agent","task":"review","ai":"qwen3.8-max","runs":"agentrun","turns":10,"untrusted":true,"why":"Orchestrates diff reading, comment drafting, test running and noise filtering"}
{"t":"step","id":"sandbox-tests","kind":"tool","label":"Run tests in sandbox","tool":"code_interpreter","on":"review-agent","effect":"read","untrusted":true,"private":true,"why":"Execute test suite against proposed changes to verify code comments"}
{"t":"step","id":"fetch-diff","kind":"tool","label":"Fetch PR diff","tool":"web_extractor","on":"review-agent","effect":"read","untrusted":true,"why":"Retrieve pull request diff and metadata for analysis"}
{"t":"step","id":"human-review","kind":"human","label":"Approve PR comments","task":"approve","subject":"review-agent","runs":"cloudflow","why":"Human reviewer approves final comments before they are posted"}
{"t":"step","id":"post-comments","kind":"act","label":"Post approved comments","effect":"publish","runs":"customer","approval":"required","why":"Submit reviewed and approved comments back to the VCS platform"}
{"t":"step","id":"done-end","kind":"end","label":"Review complete","runs":"customer","why":"Terminal state after comments are posted"}
{"t":"step","id":"rejected-end","kind":"end","label":"Review rejected","runs":"customer","why":"Terminal state when human rejects the agent output"}
{"t":"link","id":"trigger-guard","from":"pr-trigger","to":"input-guard"}
{"t":"link","id":"guard-agent","from":"input-guard","to":"review-agent"}
{"t":"link","id":"agent-human","from":"review-agent","to":"human-review"}
{"t":"link","id":"human-post","from":"human-review","to":"post-comments","kind":"branch","outcome":"approve"}
{"t":"link","id":"human-reject","from":"human-review","to":"rejected-end","kind":"branch","outcome":"reject"}
{"t":"link","id":"human-edit","from":"human-review","to":"review-agent","kind":"branch","outcome":"edit"}
{"t":"link","id":"post-done","from":"post-comments","to":"done-end"}
{"t":"ask","id":"volume","text":"How many pull requests per day need automated review?"}
{"t":"ask","id":"success","text":"What defines a successful review outcome and current baseline?"}
{"t":"done","summary":"Agent-based PR review workflow with sandbox test execution, input guardrails, noise filtering, and mandatory human approval before publishing comments."}

{"t":"say","text":"Prompt chain pattern: OCR extracts worksheet, AI tutor gives hints with guardrails, human escalation flags teachers for review."}
{"t":"assume","id":"channel","text":"Students upload photos via web or chat app"}
{"t":"assume","id":"review-trigger","text":"Teacher review flagged on low confidence or repeated attempts"}
{"t":"step","id":"upload","kind":"trigger","label":"Student uploads worksheet photo","runs":"customer","untrusted":true,"private":true}
{"t":"step","id":"guard-in","kind":"guard","label":"Screen uploaded image","product":"ai-guardrails","runs":"fc","why":"Block harmful or off-topic uploads before processing"}
{"t":"step","id":"ocr","kind":"tool","label":"Extract text from worksheet","task":"extract","tool":"pdf_parse","ai":"qwen-vl-ocr","runs":"fc","effect":"read","private":true,"why":"Convert student worksheet photo into machine-readable text"}
{"t":"step","id":"tutor","kind":"ai","label":"Generate learning hint","task":"generate","ai":"qwen3.7-plus","runs":"fc","private":true,"why":"Provide pedagogical hints instead of direct answers to the student"}
{"t":"step","id":"guard-out","kind":"guard","label":"Screen tutor hint output","product":"ai-guardrails","runs":"fc","why":"Ensure hints are safe and do not leak full answers"}
{"t":"step","id":"confidence","kind":"decide","label":"Check hint confidence level","task":"check","ai":"qwen3.8-flash","runs":"fc","why":"Determine if AI is confident enough or needs teacher intervention"}
{"t":"step","id":"deliver-hint","kind":"act","label":"Deliver hint to student","effect":"reply","runs":"customer","why":"Send the generated hint back to the student interface"}
{"t":"step","id":"flag-teacher","kind":"act","label":"Notify teacher for review","effect":"notify","runs":"customer","approval":"skip","why":"Alert teacher when AI cannot safely guide the student"}
{"t":"step","id":"teacher-review","kind":"human","label":"Teacher reviews worksheet","task":"review","runs":"cloudflow","why":"Human educator steps in to provide personalized guidance"}
{"t":"step","id":"end-ok","kind":"end","label":"Hint delivered successfully","runs":"customer"}
{"t":"step","id":"end-flagged","kind":"end","label":"Escalated to teacher","runs":"customer"}
{"t":"link","id":"upload-guard","from":"upload","to":"guard-in"}
{"t":"link","id":"guard-ocr","from":"guard-in","to":"ocr"}
{"t":"link","id":"ocr-tutor","from":"ocr","to":"tutor"}
{"t":"link","id":"tutor-guard-out","from":"tutor","to":"guard-out"}
{"t":"link","id":"guard-conf","from":"guard-out","to":"confidence"}
{"t":"link","id":"conf-deliver","from":"confidence","to":"deliver-hint","kind":"branch","label":"High confidence"}
{"t":"link","id":"conf-flag","from":"confidence","to":"flag-teacher","kind":"branch","label":"Low confidence or unclear"}
{"t":"link","id":"deliver-end","from":"deliver-hint","to":"end-ok"}
{"t":"link","id":"flag-review","from":"flag-teacher","to":"teacher-review"}
{"t":"link","id":"review-end","from":"teacher-review","to":"end-flagged"}
{"t":"ask","id":"volume","text":"How many student worksheet uploads do you expect per day?"}
{"t":"ask","id":"success","text":"What defines a successful tutoring interaction versus one needing teacher review today?"}
{"t":"done","summary":"AI tutor workflow using vision OCR for worksheets, mid-tier LLM for hint generation, output guards, and teacher escalation for low-confidence cases."}

{"t":"say","text":"Single agent pattern: extracts from photos and PDFs, checks policies, routes payout approval. Untrusted uploads plus private policy data require screening and human approval before any payout."}
{"t":"assume","id":"claim-source","text":"Claims arrive via web upload or chat app attachment","alt":"Claims arrive via email attachments"}
{"t":"assume","id":"policy-store","text":"Policy rules are in a knowledge base or database","alt":"Policy rules are hard-coded in the prompt"}
{"t":"ask","id":"volume","text":"How many claim submissions do you expect per day?"}
{"t":"ask","id":"success","text":"What defines a successful claim outcome, and what is today's baseline processing time?"}
{"t":"step","id":"claim-in","kind":"trigger","label":"Receive claim submission","runs":"customer","untrusted":true,"why":"Entry point for uploaded photos and PDFs"}
{"t":"step","id":"guard-input","kind":"guard","label":"Screen uploaded content","product":"ai-guardrails","runs":"fc","why":"Block prompt injection or harmful content in untrusted uploads"}
{"t":"step","id":"claim-agent","kind":"agent","label":"Process insurance claim","task":"plan","ai":"qwen3.7-plus","turns":10,"runs":"agentrun","private":true,"tool":"pdf_parse","why":"Multimodal agent extracts data from images and PDFs, then checks policy rules"}
{"t":"step","id":"extract-photo","kind":"tool","label":"Extract photo data","task":"see","on":"claim-agent","tool":"web_search_image","effect":"read","why":"Vision tool to read damage details from claim photos"}
{"t":"step","id":"extract-pdf","kind":"tool","label":"Parse PDF document","task":"extract","on":"claim-agent","tool":"pdf_parse","effect":"read","why":"Parse text from uploaded PDF claim forms"}
{"t":"step","id":"check-policy","kind":"knowledge","label":"Retrieve policy rules","task":"retrieve","on":"claim-agent","product":"dashvector","ai":"text-embedding-v4","effect":"read","private":true,"why":"Fetch relevant insurance policy terms for validation"}
{"t":"step","id":"decide-payout","kind":"decide","label":"Determine payout eligibility","task":"decide","after":"claim-agent","runs":"fc","why":"Route based on agent assessment of claim validity"}
{"t":"step","id":"approve-payout","kind":"human","label":"Approve claim payout","task":"approve","subject":"claim-agent","runs":"cloudflow","approval":"required","why":"Payout is a financial commitment requiring human approval under shared policy"}
{"t":"step","id":"execute-payout","kind":"act","label":"Execute approved payout","effect":"pay","runs":"customer","approval":"required","why":"Trigger payment system only after explicit human approval"}
{"t":"step","id":"payout-done","kind":"end","label":"Payout completed","runs":"customer"}
{"t":"step","id":"claim-denied","kind":"end","label":"Claim denied","runs":"customer"}
{"t":"step","id":"escalate-handoff","kind":"human","label":"Adjuster manual review","task":"takeover","runs":"customer","why":"Complex or uncertain claims need live adjuster intervention"}
{"t":"link","id":"in-guard","from":"claim-in","to":"guard-input"}
{"t":"link","id":"guard-agent","from":"guard-input","to":"claim-agent"}
{"t":"link","id":"agent-decide","from":"claim-agent","to":"decide-payout"}
{"t":"link","id":"decide-approve","from":"decide-payout","to":"approve-payout","kind":"branch","label":"Eligible for payout"}
{"t":"link","id":"decide-deny","from":"decide-payout","to":"claim-denied","kind":"branch","label":"Ineligible or fraudulent"}
{"t":"link","id":"decide-escalate","from":"decide-payout","to":"escalate-handoff","kind":"escalate","label":"Uncertain or complex case"}
{"t":"link","id":"approve-execute","from":"approve-payout","to":"execute-payout","kind":"branch","outcome":"approve"}
{"t":"link","id":"approve-reject","from":"approve-payout","to":"claim-denied","kind":"branch","outcome":"reject"}
{"t":"link","id":"approve-edit","from":"approve-payout","to":"claim-agent","kind":"branch","outcome":"edit"}
{"t":"link","id":"execute-done","from":"execute-payout","to":"payout-done"}
{"t":"done","summary":"Agent workflow extracting claim data from photos/PDFs, checking policies via retrieval, and routing payouts through mandatory human approval gates."}

{"t":"say","text":"Prompt chain pattern: OCR extraction, regulatory check, risk flagging, then human approval before submission."}
{"t":"assume","id":"upload-src","text":"Documents uploaded via web portal or object storage trigger"}
{"t":"ask","id":"volume","text":"How many customs document sets are processed per day?"}
{"t":"ask","id":"success","text":"What outcome defines success, and what is today's baseline approval rate?"}
{"t":"step","id":"upload","kind":"trigger","label":"Document upload trigger","runs":"fc","untrusted":true,"why":"Entry point for uploaded invoices and packing lists"}
{"t":"step","id":"guard-in","kind":"guard","label":"Screen uploaded files","product":"ai-guardrails","runs":"fc","why":"Block malicious payloads in untrusted uploads"}
{"t":"step","id":"parse-invoice","kind":"tool","label":"Parse customs invoice","task":"extract","tool":"pdf_parse","effect":"read","runs":"fc","untrusted":true,"why":"Extract structured fields from the invoice PDF"}
{"t":"step","id":"parse-packing","kind":"tool","label":"Parse packing list","task":"extract","tool":"pdf_parse","effect":"read","runs":"fc","untrusted":true,"why":"Extract structured fields from the packing list PDF"}
{"t":"step","id":"reg-check","kind":"ai","label":"Check destination regulations","task":"check","ai":"qwen3.8-max","runs":"fc","after":"parse-invoice","join":"all","why":"Compare extracted data against destination-country rules"}
{"t":"step","id":"risk-flag","kind":"ai","label":"Flag compliance risks","task":"classify","ai":"qwen3.7-plus","runs":"fc","why":"Identify and categorize any regulatory or data risks"}
{"t":"step","id":"compile-report","kind":"ai","label":"Compile compliance report","task":"generate","ai":"qwen3.7-plus","runs":"fc","why":"Generate a summary report for the compliance officer"}
{"t":"step","id":"guard-out","kind":"guard","label":"Screen outbound report","product":"ai-guardrails","runs":"fc","why":"Prevent private data leaks in the generated report"}
{"t":"step","id":"officer-approve","kind":"human","label":"Compliance officer review","task":"approve","subject":"compile-report","runs":"cloudflow","why":"Human gate required before consequential submission"}
{"t":"step","id":"submit","kind":"act","label":"Submit customs documents","effect":"send","runs":"customer","why":"Deliver approved documents to the customs system"}
{"t":"step","id":"done-ok","kind":"end","label":"Submission complete","runs":"customer"}
{"t":"step","id":"rejected","kind":"end","label":"Rejected by officer","runs":"customer"}
{"t":"link","id":"l-upload-guard","from":"upload","to":"guard-in"}
{"t":"link","id":"l-guard-parse-inv","from":"guard-in","to":"parse-invoice"}
{"t":"link","id":"l-guard-parse-pack","from":"guard-in","to":"parse-packing"}
{"t":"link","id":"l-inv-reg","from":"parse-invoice","to":"reg-check"}
{"t":"link","id":"l-pack-reg","from":"parse-packing","to":"reg-check"}
{"t":"link","id":"l-reg-risk","from":"reg-check","to":"risk-flag"}
{"t":"link","id":"l-risk-report","from":"risk-flag","to":"compile-report"}
{"t":"link","id":"l-report-guard","from":"compile-report","to":"guard-out"}
{"t":"link","id":"l-guard-approve","from":"guard-out","to":"officer-approve"}
{"t":"link","id":"l-approve-submit","from":"officer-approve","to":"submit","kind":"branch","outcome":"approve"}
{"t":"link","id":"l-approve-reject","from":"officer-approve","to":"rejected","kind":"branch","outcome":"reject"}
{"t":"link","id":"l-approve-edit","from":"officer-approve","to":"compile-report","kind":"branch","outcome":"edit"}
{"t":"link","id":"l-submit-done","from":"submit","to":"done-ok"}
{"t":"done","summary":"Designed a prompt-chain workflow parsing invoices and packing lists, checking regulations, flagging risks, and requiring officer approval before submission."}

{"t":"say","text":"Prompt chain pattern: extract uploaded contract clauses, retrieve playbook rules, compare and draft redlines, then lawyer approval before delivery."}
{"t":"assume","id":"upload-source","text":"Contracts arrive via file upload trigger"}
{"t":"assume","id":"playbook-store","text":"Legal playbook stored in vector database"}
{"t":"assume","id":"output-target","text":"Approved redlines delivered as downloadable document"}
{"t":"step","id":"upload","kind":"trigger","label":"Contract file upload","runs":"fc","untrusted":true,"private":true,"why":"Entry point for uploaded contract documents"}
{"t":"step","id":"parse","kind":"tool","label":"Parse contract PDF","task":"extract","tool":"pdf_parse","runs":"fc","effect":"read","untrusted":true,"private":true,"why":"Extract raw text from uploaded contract files"}
{"t":"step","id":"guard","kind":"guard","label":"Screen uploaded content","product":"ai-guardrails","runs":"fc","why":"Detect prompt injection or harmful content in uploads"}
{"t":"step","id":"extract-clauses","kind":"ai","label":"Extract contract clauses","task":"extract","ai":"qwen3.7-plus","runs":"fc","private":true,"why":"Identify and structure individual legal clauses"}
{"t":"step","id":"embed-query","kind":"knowledge","label":"Embed clause queries","task":"retrieve","product":"dashvector","ai":"text-embedding-v4","runs":"fc","why":"Vectorize extracted clauses for playbook lookup"}
{"t":"step","id":"search-playbook","kind":"knowledge","label":"Search legal playbook","task":"retrieve","product":"dashvector","runs":"fc","why":"Find relevant playbook rules for each clause"}
{"t":"step","id":"rerank","kind":"knowledge","label":"Rerank playbook matches","task":"rerank","ai":"qwen3-rerank","runs":"fc","why":"Surface most relevant playbook provisions"}
{"t":"step","id":"compare","kind":"ai","label":"Compare clauses to playbook","task":"check","ai":"qwen3.8-max","runs":"fc","private":true,"why":"Analyze deviations between contract and playbook standards"}
{"t":"step","id":"draft-redlines","kind":"ai","label":"Draft redline suggestions","task":"generate","ai":"qwen3.7-plus","runs":"fc","private":true,"why":"Generate specific redline edits based on comparison gaps"}
{"t":"step","id":"lawyer-review","kind":"human","label":"Lawyer reviews redlines","task":"approve","subject":"draft-redlines","runs":"cloudflow","approval":"required","why":"Legal professional must approve changes before delivery"}
{"t":"step","id":"deliver","kind":"act","label":"Deliver approved redlines","effect":"send","runs":"fc","private":true,"why":"Send finalized redline document to requester"}
{"t":"step","id":"rejected","kind":"end","label":"Redlines rejected","runs":"customer","why":"Terminal state when lawyer rejects the draft"}
{"t":"step","id":"completed","kind":"end","label":"Redlines delivered","runs":"customer","why":"Terminal state after successful delivery"}
{"t":"link","id":"upload-parse","from":"upload","to":"parse"}
{"t":"link","id":"parse-guard","from":"parse","to":"guard"}
{"t":"link","id":"guard-extract","from":"guard","to":"extract-clauses"}
{"t":"link","id":"extract-embed","from":"extract-clauses","to":"embed-query"}
{"t":"link","id":"embed-search","from":"embed-query","to":"search-playbook"}
{"t":"link","id":"search-rerank","from":"search-playbook","to":"rerank"}
{"t":"link","id":"rerank-compare","from":"rerank","to":"compare"}
{"t":"link","id":"compare-draft","from":"compare","to":"draft-redlines"}
{"t":"link","id":"draft-review","from":"draft-redlines","to":"lawyer-review"}
{"t":"link","id":"review-deliver","from":"lawyer-review","to":"deliver","kind":"branch","outcome":"approve"}
{"t":"link","id":"review-edit","from":"lawyer-review","to":"draft-redlines","kind":"branch","outcome":"edit"}
{"t":"link","id":"review-reject","from":"lawyer-review","to":"rejected","kind":"branch","outcome":"reject"}
{"t":"link","id":"deliver-done","from":"deliver","to":"completed"}
{"t":"ask","id":"volume","text":"How many contracts are uploaded per day?"}
{"t":"ask","id":"success","text":"What outcome defines success, and what is today's manual baseline?"}
{"t":"done","summary":"Prompt chain extracting contract clauses, retrieving playbook rules via vector search, comparing with large model, drafting redlines, and gating through lawyer approval."}

{"t":"say","text":"Single agent pattern: a scheduled agent monitors flights, researches rebooking options on disruption, and routes to human approval before acting."}
{"t":"assume","id":"flight-api","text":"Customer exposes a flight status API for the agent to poll"}
{"t":"assume","id":"rebook-api","text":"Customer booking system supports programmatic rebooking calls"}
{"t":"assume","id":"volume","text":"Monitoring covers tens of active itineraries per run"}
{"t":"ask","id":"q-volume","text":"How many itineraries are monitored per day?"}
{"t":"ask","id":"q-success","text":"What outcome defines success, and what is today's baseline resolution time?"}
{"t":"step","id":"sched","kind":"trigger","label":"Cron schedule","product":"schedulerx","runs":"fc","why":"Periodically wake the monitor agent"}
{"t":"step","id":"monitor","kind":"agent","label":"Monitor and propose rebooking","task":"plan","ai":"qwen3.8-max","tool":"mcp","turns":10,"runs":"agentrun","private":true,"why":"Polls flight API, detects disruptions, searches alternative flights via MCP tools"}
{"t":"step","id":"guard","kind":"guard","label":"Screen proposal content","product":"ai-guardrails","runs":"fc","why":"Ensure generated proposal has no prompt injection or data leaks before human review"}
{"t":"step","id":"decide","kind":"decide","label":"Route by disruption","runs":"fc","why":"Only send proposals when a real disruption was detected"}
{"t":"step","id":"approve","kind":"human","label":"Approve rebooking option","task":"approve","subject":"monitor","runs":"cloudflow","approval":"required","why":"Rebooking is a financial commitment requiring explicit human approval"}
{"t":"step","id":"rebook","kind":"act","label":"Execute approved rebooking","effect":"pay","runs":"customer","approval":"required","why":"Calls customer booking system to finalize the rebooking after approval"}
{"t":"step","id":"end-rebooked","kind":"end","label":"Rebooking completed","runs":"customer"}
{"t":"step","id":"end-rejected","kind":"end","label":"Rebooking rejected","runs":"customer"}
{"t":"step","id":"end-none","kind":"end","label":"No disruption found","runs":"customer"}
{"t":"link","id":"sched-mon","from":"sched","to":"monitor"}
{"t":"link","id":"mon-guard","from":"monitor","to":"guard"}
{"t":"link","id":"guard-decide","from":"guard","to":"decide"}
{"t":"link","id":"decide-yes","from":"decide","to":"approve","kind":"branch","label":"Disruption detected"}
{"t":"link","id":"decide-no","from":"decide","to":"end-none","kind":"branch","label":"All flights normal"}
{"t":"link","id":"appr-yes","from":"approve","to":"rebook","kind":"branch","outcome":"approve"}
{"t":"link","id":"appr-no","from":"approve","to":"end-rejected","kind":"branch","outcome":"reject"}
{"t":"link","id":"appr-edit","from":"approve","to":"monitor","kind":"branch","outcome":"edit"}
{"t":"link","id":"rebook-end","from":"rebook","to":"end-rebooked"}
{"t":"done","summary":"Scheduled agent polls flight APIs, proposes rebooking on disruption, screens output, and gates execution behind human approval in CloudFlow."}

{"t":"say","text":"Prompt chain pattern: catalog search, coupon validation, human checkout approval before applying discount."}
{"t":"assume","id":"catalog-store","text":"Product catalog is stored in a searchable database"}
{"t":"assume","id":"coupon-api","text":"Coupon system exposes a validation and apply API"}
{"t":"ask","id":"volume","text":"How many shopping assistant sessions run per day?"}
{"t":"ask","id":"success","text":"What outcome means success, and what is today's baseline conversion?"}
{"t":"step","id":"chat-in","kind":"trigger","label":"Customer chat message","runs":"customer","untrusted":true}
{"t":"step","id":"guard","kind":"guard","label":"Screen user input","product":"ai-guardrails","runs":"agentrun","why":"Block prompt injection from untrusted chat input"}
{"t":"step","id":"understand","kind":"ai","label":"Understand shopping intent","task":"extract","ai":"qwen3.7-plus","runs":"agentrun","why":"Extract product needs and coupon codes from chat"}
{"t":"step","id":"search-catalog","kind":"tool","label":"Search product catalog","task":"retrieve","runs":"customer","effect":"read","tool":"mcp","why":"Look up matching products in the customer catalog"}
{"t":"step","id":"recommend","kind":"ai","label":"Recommend products","task":"generate","ai":"qwen3.7-plus","runs":"agentrun","why":"Present tailored product recommendations to the user"}
{"t":"step","id":"validate-coupon","kind":"tool","label":"Validate coupon code","task":"check","runs":"customer","effect":"read","tool":"mcp","why":"Verify coupon eligibility before proposing it"}
{"t":"step","id":"propose-discount","kind":"ai","label":"Propose discounted cart","task":"generate","ai":"qwen3.8-flash","runs":"agentrun","why":"Summarize cart with validated coupon for approval"}
{"t":"step","id":"approve-checkout","kind":"human","label":"Approve checkout discount","task":"approve","subject":"propose-discount","runs":"cloudflow","approval":"required","why":"Human must approve financial commitment before applying coupon"}
{"t":"step","id":"apply-coupon","kind":"act","label":"Apply coupon to order","effect":"pay","runs":"customer","approval":"required","why":"Write the validated discount to the checkout system"}
{"t":"step","id":"confirm-order","kind":"ai","label":"Confirm order to user","task":"generate","ai":"qwen3.8-flash","runs":"agentrun","why":"Send final confirmation after successful checkout"}
{"t":"step","id":"declined","kind":"end","label":"Checkout declined","runs":"customer"}
{"t":"step","id":"completed","kind":"end","label":"Order completed","runs":"customer"}
{"t":"link","id":"chat-guard","from":"chat-in","to":"guard"}
{"t":"link","id":"guard-understand","from":"guard","to":"understand"}
{"t":"link","id":"understand-search","from":"understand","to":"search-catalog"}
{"t":"link","id":"search-recommend","from":"search-catalog","to":"recommend"}
{"t":"link","id":"recommend-validate","from":"recommend","to":"validate-coupon"}
{"t":"link","id":"validate-propose","from":"validate-coupon","to":"propose-discount"}
{"t":"link","id":"propose-approve","from":"propose-discount","to":"approve-checkout"}
{"t":"link","id":"approve-apply","from":"approve-checkout","to":"apply-coupon","kind":"branch","outcome":"approve"}
{"t":"link","id":"approve-declined","from":"approve-checkout","to":"declined","kind":"branch","outcome":"reject"}
{"t":"link","id":"apply-confirm","from":"apply-coupon","to":"confirm-order"}
{"t":"link","id":"confirm-done","from":"confirm-order","to":"completed"}
{"t":"done","summary":"Shopping assistant prompt chain with catalog search, coupon validation, mandatory human checkout approval, and guarded delivery."}

{"t":"say","text":"Prompt chain pattern: chat ingress, guard, retrieval over handbook sections, guarded answer with human escalation on low confidence."}
{"t":"assume","id":"channel","text":"Chat channel is DingTalk via AgentCore connector"}
{"t":"assume","id":"handbook-store","text":"HR handbook is pre-embedded in DashVector"}
{"t":"step","id":"chat-in","kind":"trigger","label":"New-hire chat message","product":"agentcore","runs":"customer","untrusted":true,"why":"Inbound chat trigger for new-hire questions"}
{"t":"step","id":"input-guard","kind":"guard","label":"Screen inbound message","product":"ai-guardrails","runs":"fc","why":"Block prompt injection and unsafe input before retrieval"}
{"t":"step","id":"embed-query","kind":"knowledge","label":"Embed question","task":"retrieve","product":"dashvector","ai":"text-embedding-v4","runs":"fc","effect":"read","why":"Convert chat text to vector for handbook lookup"}
{"t":"step","id":"search-handbook","kind":"knowledge","label":"Search handbook sections","task":"retrieve","product":"dashvector","runs":"fc","effect":"read","why":"Find relevant HR policy passages"}
{"t":"step","id":"rerank","kind":"knowledge","label":"Rerank results","task":"rerank","ai":"qwen3-rerank","runs":"fc","why":"Order passages by relevance to the question"}
{"t":"step","id":"answer","kind":"ai","label":"Draft policy answer","task":"generate","ai":"qwen3.7-plus","runs":"fc","why":"Generate grounded reply from top handbook sections"}
{"t":"step","id":"confidence","kind":"decide","label":"Check answer confidence","task":"check","ai":"qwen3.8-flash","runs":"fc","why":"Decide if answer is certain enough or needs escalation"}
{"t":"step","id":"output-guard","kind":"guard","label":"Screen outbound reply","product":"ai-guardrails","runs":"fc","why":"Prevent private data leaks and harmful content"}
{"t":"step","id":"send-reply","kind":"act","label":"Send chat reply","effect":"reply","product":"agentcore","runs":"customer","why":"Deliver the safe answer back to the new hire"}
{"t":"step","id":"hr-takeover","kind":"human","label":"HR agent takes over","task":"takeover","runs":"customer","why":"Live HR handles uncertain or complex policy cases"}
{"t":"step","id":"end-replied","kind":"end","label":"Answer delivered","runs":"customer"}
{"t":"step","id":"end-escalated","kind":"end","label":"Escalated to HR","runs":"customer"}
{"t":"link","id":"chat-to-guard","from":"chat-in","to":"input-guard"}
{"t":"link","id":"guard-to-embed","from":"input-guard","to":"embed-query"}
{"t":"link","id":"embed-to-search","from":"embed-query","to":"search-handbook"}
{"t":"link","id":"search-to-rerank","from":"search-handbook","to":"rerank"}
{"t":"link","id":"rerank-to-answer","from":"rerank","to":"answer"}
{"t":"link","id":"answer-to-confidence","from":"answer","to":"confidence"}
