{"t":"link","id":"approve-reject","from":"approve","to":"done-reject","kind":"branch","outcome":"reject"}
{"t":"link","id":"approve-edit","from":"approve","to":"draft-report","kind":"branch","outcome":"edit"}
{"t":"link","id":"apply-done","from":"apply-prod","to":"done-ok"}
