{"t":"step","id":"guard","kind":"guard","label":"Screen inbound content","product":"ai-guardrails","runs":"fc","why":"Block prompt injection or harmful content before processing."}
{"t":"step","id":"segment","kind":"ai","label":"Segment documentation","task":"extract","ai":"qwen3.8-flash","runs":"fc","after":"guard","why":"Split long documents into translatable chunks for parallel work."}
{"t":"each","id":"lang-loop","over":"ES, FR, DE, JA, ZH, PT","parallel":true}
{"t":"step","id":"translate","kind":"ai","label":"Translate segment","task":"translate","ai":"qwen3.7-plus","runs":"fc","after":"segment","repeat":"lang-loop","why":"Translate each segment into the target language using mid-tier model."}
{"t":"step","id":"score","kind":"ai","label":"Score translation quality","task":"check","ai":"qwen3.8-flash","runs":"fc","after":"translate","repeat":"lang-loop","why":"Automatically evaluate fluency and accuracy of translated segment."}
{"t":"step","id":"route","kind":"decide","label":"Route by confidence","task":"decide","runs":"fc","after":"score","repeat":"lang-loop","why":"Determine if AI translation is sufficient or needs human review."}
{"t":"step","id":"human-tx","kind":"human","label":"Human translator review","task":"takeover","runs":"cloudflow","after":"route","repeat":"lang-loop","why":"Manual translation for segments failing automated quality checks."}
{"t":"step","id":"assemble","kind":"ai","label":"Assemble final document","task":"generate","ai":"qwen3.7-plus","runs":"fc","join":"all","after":"lang-loop","why":"Merge approved and human-translated segments into final outputs."}
{"t":"step","id":"publish","kind":"act","label":"Publish translations","effect":"publish","runs":"customer","after":"assemble","approval":"required","why":"Deliver finalized multilingual documentation to the target system."}
{"t":"step","id":"done-pub","kind":"end","label":"Published successfully","runs":"customer","after":"publish","why":"Terminal state after successful publication."}
{"t":"link","id":"ingest-guard","from":"ingest","to":"guard"}
