{"t":"step","id":"embed-reqs","kind":"knowledge","label":"Embed parsed requirements","task":"retrieve","product":"dashvector","ai":"text-embedding-v4","runs":"fc","why":"Convert extracted text to vectors for semantic search against the policy library"}
{"t":"step","id":"search-policy","kind":"knowledge","label":"Search approved policy library","task":"retrieve","product":"dashvector","runs":"fc","after":"embed-reqs","why":"Retrieve relevant approved policy snippets matching the RFP requirements"}
{"t":"step","id":"rerank-policy","kind":"knowledge","label":"Rerank policy matches","task":"rerank","ai":"qwen3-rerank","runs":"fc","after":"search-policy","why":"Ensure only the most relevant policy context is passed to the drafting model"}
{"t":"step","id":"draft-answers","kind":"ai","label":"Draft RFP answers","task":"generate","ai":"qwen3.7-plus","runs":"fc","after":"rerank-policy","why":"Generate proposed answers grounded strictly in the retrieved approved policies"}
{"t":"step","id":"hallucination-check","kind":"ai","label":"Check for hallucinations","task":"check","ai":"qwen3.8-max","runs":"fc","after":"draft-answers","why":"Verify drafted answers are factually supported by the retrieved policy context without hallucinations"}
{"t":"step","id":"route-sme","kind":"decide","label":"Route to appropriate SME","task":"plan","ai":"qwen3.8-flash","runs":"fc","after":"hallucination-check","why":"Determine which Subject Matter Expert should review the drafted answers based on topic"}
