{"t":"link","id":"search-rerank","from":"search-policy","to":"rerank-policy"}
{"t":"link","id":"rerank-draft","from":"rerank-policy","to":"draft-answers"}
{"t":"link","id":"draft-hallucination","from":"draft-answers","to":"hallucination-check"}
{"t":"link","id":"hallucination-route","from":"hallucination-check","to":"route-sme"}
{"t":"link","id":"route-sme-approve","from":"route-sme","to":"sme-approve"}
{"t":"link","id":"sme-deliver","from":"sme-approve","to":"deliver-rfp","kind":"branch","outcome":"approve"}
{"t":"link","id":"sme-edit","from":"sme-approve","to":"draft-answers","kind":"branch","outcome":"edit"}
