{"t":"step","id":"translate","kind":"ai","label":"Translate segment","task":"translate","ai":"qwen3.7-plus","runs":"fc","repeat":"lang-loop","why":"Mid-tier model handles translation generation across six target languages"}
{"t":"step","id":"score","kind":"ai","label":"Score translation quality","task":"check","ai":"qwen3.8-max","runs":"fc","repeat":"lang-loop","after":"translate","why":"Large model evaluates fluency, accuracy and terminology consistency"}
{"t":"step","id":"route","kind":"decide","label":"Route by confidence","task":"decide","runs":"fc","repeat":"lang-loop","after":"score","why":"Exclusive branch sends low scores to humans and high scores to assembly"}
