{"t":"step","id":"rank","kind":"knowledge","label":"Rank policies","task":"rerank","ai":"qwen3-rerank","runs":"fc","repeat":"per-req","after":"retrieve","why":"Reorder retrieved policies by relevance"}
{"t":"step","id":"draft","kind":"ai","label":"Draft answer","task":"generate","ai":"qwen3.7-plus","runs":"fc","repeat":"per-req","after":"rank","why":"Generate grounded response from top policies"}
