{"t":"say","text":"Prompt chain pattern: vision extraction, pedagogical hint generation, safety guard, and teacher escalation via prompt chain."}
{"t":"assume","id":"channel","text":"Students upload photos via web or chat app"}
{"t":"assume","id":"review-channel","text":"Teacher review delivered via notification or email"}
{"t":"ask","id":"volume","text":"How many worksheet submissions per day?"}
{"t":"ask","id":"success","text":"What defines a successful hint, and what is the baseline?"}
{"t":"step","id":"in","kind":"trigger","label":"Receive worksheet photo","runs":"customer","untrusted":true,"why":"Entry point for student photo uploads"}
{"t":"step","id":"guard-in","kind":"guard","label":"Screen inbound content","product":"ai-guardrails","runs":"fc","why":"Block harmful or non-worksheet images before processing"}
{"t":"step","id":"extract","kind":"ai","label":"Read worksheet image","task":"see","ai":"qwen3.7-plus","runs":"fc","why":"Extract problem text and student work from photo"}
{"t":"step","id":"assess","kind":"ai","label":"Assess understanding","task":"check","ai":"qwen3.8-max","runs":"fc","after":"extract","why":"Determine if student needs hints or teacher review"}
{"t":"step","id":"route","kind":"decide","label":"Route workflow","task":"decide","runs":"fc","after":"assess","why":"Choose between hint generation and teacher escalation"}
{"t":"step","id":"hint","kind":"ai","label":"Generate pedagogical hint","task":"generate","ai":"qwen3.8-max","runs":"fc","private":true,"why":"Produce helpful hint without giving away the answer"}
{"t":"step","id":"guard-out","kind":"guard","label":"Guard hint output","product":"ai-guardrails","runs":"fc","after":"hint","why":"Ensure hint does not leak answers or unsafe content"}
{"t":"step","id":"reply","kind":"act","label":"Deliver hint to student","effect":"reply","runs":"customer","after":"guard-out","why":"Send the safe hint back to the student"}
{"t":"step","id":"flag","kind":"ai","label":"Draft teacher summary","task":"summarise","ai":"qwen3.8-flash","runs":"fc","private":true,"why":"Summarize issue for teacher review"}
{"t":"step","id":"approve-flag","kind":"human","label":"Approve teacher alert","task":"approve","subject":"flag","runs":"cloudflow","after":"flag","approval":"required","why":"Prevent false alerts to teachers"}
{"t":"step","id":"notify-teacher","kind":"act","label":"Notify teacher","effect":"send","product":"direct-mail","runs":"fc","after":"approve-flag","why":"Escalate to teacher for manual intervention"}
{"t":"step","id":"end-hint","kind":"end","label":"Hint delivered","runs":"customer"}
{"t":"step","id":"end-flagged","kind":"end","label":"Flagged for teacher","runs":"customer"}
{"t":"step","id":"end-rejected","kind":"end","label":"Alert rejected","runs":"customer"}
{"t":"link","id":"in-guard","from":"in","to":"guard-in","kind":"next","label":"Photo received"}
{"t":"link","id":"guard-extract","from":"guard-in","to":"extract","kind":"next","label":"Safe content"}
{"t":"link","id":"extract-assess","from":"extract","to":"assess","kind":"next","label":"Text extracted"}
{"t":"link","id":"assess-route","from":"assess","to":"route","kind":"next","label":"Assessment done"}
{"t":"link","id":"route-hint","from":"route","to":"hint","kind":"branch","label":"Student needs hint"}
{"t":"link","id":"route-flag","from":"route","to":"flag","kind":"branch","label":"Needs teacher review"}
{"t":"link","id":"hint-guard","from":"hint","to":"guard-out","kind":"next","label":"Hint generated"}
{"t":"link","id":"guard-reply","from":"guard-out","to":"reply","kind":"next","label":"Hint safe"}
{"t":"link","id":"reply-end","from":"reply","to":"end-hint","kind":"next","label":"Delivered"}
{"t":"link","id":"flag-approve","from":"flag","to":"approve-flag","kind":"next","label":"Summary drafted"}
{"t":"link","id":"approve-notify","from":"approve-flag","to":"notify-teacher","kind":"branch","outcome":"approve","label":"Approved"}
{"t":"link","id":"approve-reject","from":"approve-flag","to":"end-rejected","kind":"branch","outcome":"reject","label":"Rejected"}
{"t":"link","id":"notify-end","from":"notify-teacher","to":"end-flagged","kind":"next","label":"Sent"}
{"t":"done","summary":"AI tutor prompt chain using vision extraction, pedagogical hinting with safety guards, and teacher escalation with approval."}

{"t":"say","text":"Prompt chain pattern: OCR and vision extract claims, policy check validates, human approves payouts before disbursement."}
{"t":"assume","id":"policy-store","text":"Policy data lives in a customer database or API"}
{"t":"assume","id":"payout-sys","text":"Payout system is an external API called by act step"}
{"t":"ask","id":"volume","text":"How many claim submissions (photos or PDFs) do you expect per day?"}
{"t":"ask","id":"success","text":"What outcome defines success, and what is today's baseline approval rate?"}
{"t":"step","id":"claim-in","kind":"trigger","label":"Receive claim upload","runs":"customer","untrusted":true,"why":"Entry point for uploaded claim photos and PDFs"}
{"t":"step","id":"input-guard","kind":"guard","label":"Screen uploaded files","product":"ai-guardrails","runs":"fc","why":"Block prompt injection or harmful content in uploads"}
{"t":"step","id":"route-type","kind":"decide","label":"Route by file type","task":"classify","ai":"qwen3.8-flash","runs":"fc","why":"Send images to vision and PDFs to OCR extraction"}
{"t":"step","id":"extract-img","kind":"ai","label":"Extract from photo","task":"extract","ai":"qwen3.7-plus","runs":"fc","why":"Vision model reads claim details from uploaded photos"}
{"t":"step","id":"parse-pdf","kind":"tool","label":"Parse PDF text","tool":"pdf_parse","runs":"fc","effect":"read","why":"Extract raw text from uploaded PDF claim documents"}
{"t":"step","id":"extract-pdf","kind":"ai","label":"Extract from PDF text","task":"extract","ai":"qwen3.8-flash","runs":"fc","after":"parse-pdf","why":"Structure extracted PDF text into claim fields"}
{"t":"step","id":"merge-data","kind":"ai","label":"Merge claim fields","task":"extract","ai":"qwen3.8-flash","runs":"fc","join":"any","why":"Unify image and PDF extractions into one claim record"}
{"t":"step","id":"check-policy","kind":"agent","label":"Check policy rules","task":"check","ai":"qwen3.7-plus","runs":"agentrun","turns":5,"why":"Validate extracted claim against policy database"}
{"t":"step","id":"lookup-api","kind":"tool","label":"Query policy DB","tool":"mcp","on":"check-policy","runs":"customer","effect":"read","private":true,"why":"Read policy coverage and limits from customer system"}
{"t":"step","id":"route-decision","kind":"decide","label":"Route by policy result","task":"check","ai":"qwen3.8-flash","runs":"fc","why":"Decide if claim needs payout approval or rejection"}
{"t":"step","id":"approve-payout","kind":"human","label":"Approve claim payout","task":"approve","subject":"check-policy","runs":"cloudflow","approval":"required","why":"Human must approve financial payout per shared policy"}
{"t":"step","id":"pay-act","kind":"act","label":"Execute payout","effect":"pay","runs":"customer","why":"Call payout system after human approval"}
{"t":"step","id":"paid-end","kind":"end","label":"Payout completed","runs":"customer"}
{"t":"step","id":"rejected-end","kind":"end","label":"Claim rejected","runs":"customer"}
{"t":"link","id":"in-guard","from":"claim-in","to":"input-guard"}
{"t":"link","id":"guard-route","from":"input-guard","to":"route-type"}
{"t":"link","id":"route-img","from":"route-type","to":"extract-img","kind":"branch","label":"Image file"}
{"t":"link","id":"route-pdf","from":"route-type","to":"parse-pdf","kind":"branch","label":"PDF file"}
{"t":"link","id":"pdf-parse-extract","from":"parse-pdf","to":"extract-pdf"}
{"t":"link","id":"img-merge","from":"extract-img","to":"merge-data"}
{"t":"link","id":"pdf-merge","from":"extract-pdf","to":"merge-data"}
{"t":"link","id":"merge-check","from":"merge-data","to":"check-policy"}
{"t":"link","id":"check-route","from":"check-policy","to":"route-decision"}
{"t":"link","id":"route-approve","from":"route-decision","to":"approve-payout","kind":"branch","label":"Valid claim"}
{"t":"link","id":"route-reject","from":"route-decision","to":"rejected-end","kind":"branch","label":"Invalid or denied"}
{"t":"link","id":"appr-pay","from":"approve-payout","to":"pay-act","kind":"branch","outcome":"approve"}
{"t":"link","id":"appr-reject","from":"approve-payout","to":"rejected-end","kind":"branch","outcome":"reject"}
{"t":"link","id":"appr-edit","from":"approve-payout","to":"check-policy","kind":"branch","outcome":"edit"}
{"t":"link","id":"pay-end","from":"pay-act","to":"paid-end"}
{"t":"done","summary":"Claim processing agent with guarded extraction, policy-checking agent, human payout approval and pay/reject routing."}

{"t":"say","text":"Single agent pattern: one coding agent reviews PRs, runs tests in sandbox, filters noise, then routes to human approval."}
{"t":"assume","id":"pr-source","text":"PR events arrive via webhook from GitHub or GitLab"}
{"t":"assume","id":"sandbox-access","text":"Agent Sandbox is available in ap-southeast-1"}
{"t":"ask","id":"volume","text":"How many pull requests per day will this agent review?"}
{"t":"ask","id":"success","text":"What outcome means success, and what is today's baseline review time or defect rate?"}
{"t":"step","id":"pr-trigger","kind":"trigger","label":"PR webhook received","product":"eventbridge","runs":"fc","untrusted":true,"why":"Ingest pull request events from the repository platform"}
{"t":"step","id":"input-guard","kind":"guard","label":"Screen PR payload","product":"ai-guardrails","runs":"fc","why":"Detect prompt injection or malicious content in untrusted PR data"}
{"t":"step","id":"review-agent","kind":"agent","label":"Review PR code","task":"review","ai":"qwen3.8-max","tool":"code_interpreter","turns":10,"runs":"agentrun","untrusted":true,"private":true,"approval":"required","why":"Analyze diff, run tests in sandbox, verify findings, filter noise and draft comments"}
{"t":"step","id":"human-review","kind":"human","label":"Approve final review","task":"approve","subject":"review-agent","runs":"cloudflow","why":"Human reviewer approves or edits the agent's final PR comments before posting"}
{"t":"step","id":"post-comments","kind":"act","label":"Post approved comments","effect":"publish","runs":"customer","approval":"required","why":"Publish approved review comments to the pull request on the repository platform"}
{"t":"step","id":"posted","kind":"end","label":"Comments posted","runs":"customer","why":"Successful completion path"}
{"t":"step","id":"declined","kind":"end","label":"Review declined","runs":"customer","why":"Human rejected the agent review"}
{"t":"link","id":"trigger-guard","from":"pr-trigger","to":"input-guard"}
{"t":"link","id":"guard-agent","from":"input-guard","to":"review-agent"}
{"t":"link","id":"agent-human","from":"review-agent","to":"human-review"}
{"t":"link","id":"human-post","from":"human-review","to":"post-comments","kind":"branch","outcome":"approve"}
{"t":"link","id":"human-edit","from":"human-review","to":"review-agent","kind":"branch","outcome":"edit"}
{"t":"link","id":"human-decline","from":"human-review","to":"declined","kind":"branch","outcome":"reject"}
{"t":"link","id":"post-done","from":"post-comments","to":"posted"}
{"t":"done","summary":"Coding agent reviews PRs with sandboxed test execution, guarded input, and mandatory human approval before publishing comments."}

{"t":"say","text":"Prompt chain pattern: extract clauses, retrieve playbook, compare and draft redlines, then lawyer approval before delivery."}
{"t":"assume","id":"upload-source","text":"Contracts arrive via file upload or storage trigger","alt":"Contracts arrive via inbound email"}
{"t":"assume","id":"playbook-store","text":"Legal playbook is stored in a vector database","alt":"Legal playbook is in object storage files"}
{"t":"assume","id":"delivery-method","text":"Approved redlines are saved to storage for download","alt":"Approved redlines are emailed to the requester"}
{"t":"ask","id":"volume","text":"How many contracts are uploaded per day?"}
{"t":"ask","id":"success","text":"What outcome defines success, and what is today's baseline review time?"}
{"t":"step","id":"upload","kind":"trigger","label":"Contract upload trigger","runs":"fc","untrusted":true,"private":true,"why":"Entry point for uploaded contract files"}
{"t":"step","id":"parse","kind":"tool","label":"Parse contract document","task":"extract","tool":"pdf_parse","runs":"fc","effect":"read","private":true,"why":"Extract raw text from PDF or DOCX contract"}
{"t":"step","id":"guard","kind":"guard","label":"Screen contract content","product":"ai-guardrails","runs":"fc","why":"Detect prompt injection or harmful content in untrusted uploads"}
{"t":"step","id":"extract","kind":"ai","label":"Extract contract clauses","task":"extract","ai":"qwen3.7-plus","runs":"fc","private":true,"why":"Identify and structure individual clauses from contract text"}
{"t":"step","id":"retrieve","kind":"knowledge","label":"Retrieve playbook rules","task":"retrieve","product":"dashvector","ai":"text-embedding-v4","runs":"fc","why":"Fetch relevant legal playbook provisions for comparison"}
{"t":"step","id":"rank","kind":"knowledge","label":"Rank playbook matches","task":"rerank","ai":"qwen3-rerank","runs":"fc","why":"Score and order retrieved rules by relevance to extracted clauses"}
{"t":"step","id":"compare","kind":"ai","label":"Compare against playbook","task":"check","ai":"qwen3.8-max","runs":"fc","private":true,"why":"Analyze deviations between contract clauses and playbook standards"}
