{"t":"say","text":"Single agent pattern: CloudMonitor trigger feeds an SRE agent that gathers evidence, reasons, and proposes a rollback for approval."}
{"t":"assume","id":"alert-source","text":"CloudMonitor alerts arrive via EventBridge webhook"}
{"t":"assume","id":"rollback-target","text":"Rollback targets a deployment or config change"}
{"t":"assume","id":"log-store","text":"SLS holds application logs; ARMS or metrics in CloudMonitor"}
{"t":"step","id":"alert-in","kind":"trigger","label":"CloudMonitor alert","product":"eventbridge","runs":"fc","untrusted":true,"why":"Entry point for incoming infrastructure alerts"}
{"t":"step","id":"guard","kind":"guard","label":"Screen alert payload","product":"ai-guardrails","runs":"fc","why":"Validate untrusted webhook input before agent processing"}
{"t":"step","id":"sre-agent","kind":"agent","label":"SRE investigation agent","task":"plan","ai":"qwen3.8-max","runs":"agentrun","turns":10,"private":true,"why":"Gathers logs and metrics, reasons through hypotheses to find root cause"}
