{"t":"link","id":"draft-approve","from":"draft-proposal","to":"approve","kind":"next","label":"Proposal ready"}
{"t":"link","id":"approve-execute","from":"approve","to":"execute-rollback","kind":"branch","outcome":"approve","label":"Approved"}
{"t":"link","id":"approve-reject","from":"approve","to":"done-reject","kind":"branch","outcome":"reject","label":"Rejected"}
{"t":"link","id":"execute-done","from":"execute-rollback","to":"done-ok","kind":"next","label":"Rollback applied"}
